// Parent class
class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void sound() {
        System.out.println(name + " makes a sound.");
    }

    void sleep() {
        System.out.println(name + " is sleeping.");
    }
}

// Child class 1 — inherits Animal
class Dog extends Animal {

    Dog(String name) {
        super(name); // calls Animal constructor
    }

    @Override
    void sound() {
        System.out.println(name + " says: Woof!");
    }
}

// Child class 2 — inherits Animal
class Cat extends Animal {

    Cat(String name) {
        super(name); // calls Animal constructor
    }

    @Override
    void sound() {
        System.out.println(name + " says: Meow!");
    }
}

// Main class
public class Main {
    public static void main(String[] args) {

        // Polymorphism: parent reference, child object
        Animal a1 = new Dog("Bruno");
        Animal a2 = new Cat("Whiskers");

        a1.sound();  // Dog version called at runtime
        a2.sound();  // Cat version called at runtime

        a1.sleep();  // inherited from Animal
        a2.sleep();  // inherited from Animal
    }
}

